package com.pingworlds;

/**
 * The only account distinction that affects which worlds you can log into: members vs free-to-play.
 * (Ironman/HCIM don't restrict world choice, so they aren't modelled here.) We cannot detect this
 * before login, so the user tells us once via config.
 */
public enum AccountType
{
	MEMBERS("Members"),
	FREE_TO_PLAY("Free-to-play");

	private final String displayName;

	AccountType(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.pingworlds;

/**
 * A play-style profile: a named bundle of world filters for a common goal. The filtering logic
 * that each profile maps to arrives in M5 — here it is just the choice the user makes in config.
 */
public enum PingProfile
{
	STABLE_BOSSING("Stable bossing / Inferno"),
	LEAGUES("Leagues"),
	FREE_TO_PLAY("Free-to-play"),
	PVP("PvP"),
	CUSTOM("Custom (my world list)");

	private final String displayName;

	PingProfile(String displayName)
	{
		this.displayName = displayName;
	}

	// RuneLite renders enums as a dropdown using toString(), so this controls the label the user sees.
	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.pingworlds;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(PingWorldsConfig.GROUP)
public interface PingWorldsConfig extends Config
{
	/**
	 * The config group name. Kept as a constant so it is never re-typed (and so a future rename is a
	 * one-line change). Per AGENTS.md, this group must never be renamed without a migration, because
	 * renaming silently resets everyone's saved settings.
	 */
	String GROUP = "pingworlds";

	// ---------------------------------------------------------------------------------------------
	// What to ping (smart selection). The logic that reads these arrives in M4/M5.
	// ---------------------------------------------------------------------------------------------

	@ConfigItem(
		keyName = "profile",
		name = "Play-style profile",
		description = "Pick a goal; the plugin filters worlds to match it.",
		position = 0
	)
	default PingProfile profile()
	{
		return PingProfile.STABLE_BOSSING;
	}

	@ConfigItem(
		keyName = "region",
		name = "Region",
		description = "Which server region to consider. Auto matches your currently-selected world.",
		position = 1
	)
	default RegionOption region()
	{
		return RegionOption.AUTO;
	}

	@ConfigItem(
		keyName = "accountType",
		name = "Account type",
		description = "Members or free-to-play. Decides which worlds you can actually log into.",
		position = 2
	)
	default AccountType accountType()
	{
		return AccountType.MEMBERS;
	}

	@ConfigItem(
		keyName = "customWorlds",
		name = "Custom world list",
		description = "Comma-separated world numbers, used when the profile is Custom (e.g. 301, 302, 330).",
		position = 3
	)
	default String customWorlds()
	{
		return "";
	}

	@Range(min = 3, max = 20)
	@ConfigItem(
		keyName = "activeWorldCount",
		name = "Worlds to show",
		description = "How many worlds to list in the panel (best-first). All eligible worlds are still scanned for ping/jitter in the background.",
		position = 4
	)
	default int worldsToShow()
	{
		return 10;
	}

	// ---------------------------------------------------------------------------------------------
	// Sampling. How many recent pings define a world's average + jitter.
	// ---------------------------------------------------------------------------------------------

	@Range(min = 3, max = 100)
	@ConfigItem(
		keyName = "sampleWindow",
		name = "Samples per world",
		description = "How many recent pings to average per world (also drives the jitter estimate).",
		position = 5
	)
	default int sampleWindow()
	{
		return 10;
	}

	// ---------------------------------------------------------------------------------------------
	// What earns a green check. Both thresholds must be met (M3).
	// ---------------------------------------------------------------------------------------------

	@Range(min = 10, max = 1000)
	@ConfigItem(
		keyName = "avgThresholdMs",
		name = "Max average ping (ms)",
		description = "A world is green only if its average ping is under this.",
		position = 7
	)
	default int avgThresholdMs()
	{
		return 80;
	}

	@Range(min = 1, max = 500)
	@ConfigItem(
		keyName = "jitterThresholdMs",
		name = "Max jitter (ms)",
		description = "A world is green only if its jitter (consistency) is under this.",
		position = 8
	)
	default int jitterThresholdMs()
	{
		return 15;
	}
}

package com.pingworlds;

import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.IntConsumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.PluginPanel;

/**
 * The sidebar panel: a compact, World-Hopper-style table of worlds with a Stability (check/cross)
 * column plus players, ping and jitter. Pure view — it renders whatever {@link WorldStatus} rows it
 * is handed and reports clicks back through a callback. display() must be called on the Swing EDT.
 */
class PingWorldsPanel extends PluginPanel
{
	private static final Color GREEN = new Color(101, 186, 106);
	private static final Color RED = new Color(214, 92, 92);
	private static final Color GREY = new Color(150, 150, 150);
	private static final Color TEXT = new Color(220, 220, 220);
	private static final Color ROW_BG = new Color(42, 46, 54);
	private static final Color ROW_HOVER = new Color(54, 58, 68);
	private static final Color CURRENT_BG = new Color(35, 58, 82);
	private static final Color CURRENT_HOVER = new Color(44, 70, 98);

	private static final ImageIcon CHECK = drawCheck();
	private static final ImageIcon CROSS = drawCross();
	private static final ImageIcon PENDING = drawPending();

	private final IntConsumer onWorldSelected;
	private final JLabel subtitle = new JLabel();
	private final JPanel rows = new JPanel();

	PingWorldsPanel(IntConsumer onWorldSelected)
	{
		this.onWorldSelected = onWorldSelected;

		setLayout(new BorderLayout(0, 6));
		setBorder(BorderFactory.createEmptyBorder(8, 6, 8, 6));

		JPanel head = new JPanel(new BorderLayout());
		head.setBorder(BorderFactory.createEmptyBorder(0, 2, 4, 2));
		JLabel title = new JLabel("Ping Worlds");
		title.setFont(title.getFont().deriveFont(Font.BOLD, 15f));
		head.add(title, BorderLayout.NORTH);
		subtitle.setFont(subtitle.getFont().deriveFont(11f));
		subtitle.setForeground(GREY);
		head.add(subtitle, BorderLayout.SOUTH);
		add(head, BorderLayout.NORTH);

		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		add(rows, BorderLayout.CENTER);

		display(java.util.Collections.emptyList(), -1, "Scanning worlds…");
	}

	/** Render the given rows. Must be called on the Swing EDT. */
	void display(List<WorldStatus> statuses, int currentWorldId, String status)
	{
		subtitle.setText(status);
		rows.removeAll();

		if (statuses.isEmpty())
		{
			JLabel empty = new JLabel("No worlds yet — scanning…");
			empty.setForeground(GREY);
			empty.setBorder(BorderFactory.createEmptyBorder(6, 2, 0, 2));
			rows.add(empty);
		}
		else
		{
			rows.add(headerRow());
			rows.add(Box.createVerticalStrut(2));
			for (WorldStatus s : statuses)
			{
				rows.add(row(s, s.getWorldId() == currentWorldId));
				rows.add(Box.createVerticalStrut(3));
			}
		}
		rows.add(Box.createVerticalGlue());
		rows.revalidate();
		rows.repaint();
	}

	private JPanel headerRow()
	{
		JPanel h = new JPanel(new BorderLayout(4, 0));
		h.setOpaque(false);
		h.setBorder(BorderFactory.createEmptyBorder(0, 6, 2, 6));
		h.setMaximumSize(new Dimension(Integer.MAX_VALUE, 14));

		JPanel west = rowSection();
		west.add(fixed(headerLabel("", SwingConstants.CENTER), 16));
		west.add(fixed(headerLabel("World", SwingConstants.LEFT), 34));
		west.add(fixed(headerLabel("Pl", SwingConstants.RIGHT), 34));
		h.add(west, BorderLayout.WEST);

		JLabel act = headerLabel("Activity", SwingConstants.LEFT);
		act.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 0));
		h.add(act, BorderLayout.CENTER);

		JPanel east = rowSection();
		east.add(fixed(headerLabel("Png", SwingConstants.RIGHT), 30));
		east.add(Box.createHorizontalStrut(4));
		east.add(fixed(headerLabel("Jit", SwingConstants.RIGHT), 26));
		h.add(east, BorderLayout.EAST);

		return h;
	}

	private JPanel row(WorldStatus s, boolean current)
	{
		final Color base = current ? CURRENT_BG : ROW_BG;
		final Color hover = current ? CURRENT_HOVER : ROW_HOVER;

		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		row.setBackground(base);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		// West: stability icon + world number + player count
		JPanel west = rowSection();
		JLabel stab = new JLabel(!s.hasData() ? PENDING : (s.isConsistent() ? CHECK : CROSS));
		west.add(fixed(stab, 16));
		JLabel world = new JLabel(String.valueOf(s.getWorldId()));
		world.setForeground(TEXT);
		world.setFont(world.getFont().deriveFont(Font.BOLD, 12f));
		west.add(fixed(world, 34));
		JLabel players = right(new JLabel(s.getPlayers() >= 0 ? String.valueOf(s.getPlayers()) : "-"));
		players.setForeground(GREY);
		players.setFont(players.getFont().deriveFont(10f));
		west.add(fixed(players, 34));
		row.add(west, BorderLayout.WEST);

		// Center: activity
		JLabel activity = new JLabel(truncate(s.getActivity(), 12));
		activity.setForeground(GREY);
		activity.setFont(activity.getFont().deriveFont(11f));
		activity.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 0));
		row.add(activity, BorderLayout.CENTER);

		// East: ping (coloured) + jitter
		JPanel east = rowSection();
		JLabel ping = right(new JLabel(s.hasData() ? String.valueOf(s.getAverage()) : "—"));
		ping.setFont(ping.getFont().deriveFont(Font.BOLD, 12f));
		ping.setForeground(!s.hasData() ? GREY : (s.isConsistent() ? GREEN : RED));
		east.add(fixed(ping, 30));
		east.add(Box.createHorizontalStrut(4));
		JLabel jitter = right(new JLabel(s.hasData() ? String.valueOf(s.getJitter()) : "—"));
		jitter.setForeground(GREY);
		jitter.setFont(jitter.getFont().deriveFont(11f));
		east.add(fixed(jitter, 26));
		row.add(east, BorderLayout.EAST);

		row.setToolTipText(tooltip(s, current));

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				onWorldSelected.accept(s.getWorldId());
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(hover);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(base);
			}
		});

		return row;
	}

	private static JPanel rowSection()
	{
		JPanel p = new JPanel();
		p.setOpaque(false);
		p.setLayout(new BoxLayout(p, BoxLayout.X_AXIS));
		return p;
	}

	private static JLabel headerLabel(String text, int align)
	{
		JLabel l = new JLabel(text, align);
		l.setForeground(GREY);
		l.setFont(l.getFont().deriveFont(10f));
		return l;
	}

	private static JLabel right(JLabel l)
	{
		l.setHorizontalAlignment(SwingConstants.RIGHT);
		return l;
	}

	private static Component fixed(JLabel l, int width)
	{
		Dimension d = new Dimension(width, 18);
		l.setPreferredSize(d);
		l.setMinimumSize(d);
		l.setMaximumSize(d);
		return l;
	}

	private static String tooltip(WorldStatus s, boolean current)
	{
		StringBuilder b = new StringBuilder("World ").append(s.getWorldId());
		if (!s.getRegionLabel().isEmpty())
		{
			b.append(" (").append(s.getRegionLabel()).append(')');
		}
		if (s.hasData())
		{
			b.append(" — avg ").append(s.getAverage()).append(" ms, jitter ")
				.append(s.getJitter()).append(" ms, ").append(s.getSamples()).append(" pings");
		}
		else
		{
			b.append(" — measuring…");
		}
		b.append(current ? "  •  current world" : "  •  click to switch");
		return b.toString();
	}

	private static String truncate(String s, int max)
	{
		if (s.length() <= max)
		{
			return s;
		}
		return s.substring(0, Math.max(0, max - 1)).trim() + "…";
	}

	// ---- Drawn status icons (crisp check / cross / pending dot) -------------------------------------

	private static ImageIcon drawCheck()
	{
		return icon(g ->
		{
			g.setColor(GREEN);
			g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawPolyline(new int[]{2, 6, 12}, new int[]{8, 12, 3}, 3);
		});
	}

	private static ImageIcon drawCross()
	{
		return icon(g ->
		{
			g.setColor(RED);
			g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(3, 3, 11, 11);
			g.drawLine(11, 3, 3, 11);
		});
	}

	private static ImageIcon drawPending()
	{
		return icon(g ->
		{
			g.setColor(GREY);
			g.fillOval(4, 4, 6, 6);
		});
	}

	private interface IconPainter
	{
		void paint(Graphics2D g);
	}

	private static ImageIcon icon(IconPainter painter)
	{
		BufferedImage img = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		painter.paint(g);
		g.dispose();
		return new ImageIcon(img);
	}
}

package com.pingworlds;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.WorldService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.worldhopper.ping.Ping;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.WorldUtil;
import net.runelite.http.api.worlds.World;
import net.runelite.http.api.worlds.WorldRegion;
import net.runelite.http.api.worlds.WorldResult;
import net.runelite.http.api.worlds.WorldType;

@Slf4j
@PluginDescriptor(
	name = "Ping Worlds",
	description = "Scan worlds for ping and jitter and see which are the most stable to log into",
	tags = {"ping", "world", "latency", "login", "hop", "jitter"}
)
public class PingWorldsPlugin extends Plugin
{
	// Worlds at or above this player count are treated as full (matches RuneLite's World Hopper).
	private static final int FULL_WORLD_PLAYERS = 1950;

	// Small delay before the first ping so the world list has a chance to load after startup.
	private static final int INITIAL_DELAY_SECONDS = 2;

	// The sweep: process worlds in batches; ping each world in a batch this many times (rounds) before
	// moving to the next batch, and don't revisit a batch until the whole sweep has finished.
	private static final int BATCH_SIZE = 10;
	private static final int ROUNDS_PER_BATCH = 5;

	// Steady, gentle spacing between individual pings (~5 pings/second, to varied servers).
	private static final int PING_SPACING_MS = 200;

	// Don't rebuild the panel more often than this (the sweep ticks several times a second).
	private static final long PANEL_REFRESH_MS = 500;

	@Inject
	private Client client;

	@Inject
	private WorldService worldService;

	@Inject
	private PingWorldsConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ClientThread clientThread;

	private PingWorldsPanel panel;
	private NavigationButton navButton;

	private ScheduledExecutorService executor;
	private ScheduledFuture<?> pingTask;

	// Per-world rolling stats. Written on the executor thread, read from the Swing thread, so a
	// concurrent map plus WorldPingStats' own synchronization keeps it safe.
	private final Map<Integer, WorldPingStats> statsByWorld = new ConcurrentHashMap<>();

	// Worlds the user explicitly clicked. Written from the Swing thread, read from the executor
	// thread, so it is synchronized; insertion order preserved.
	private final Set<Integer> pinned = Collections.synchronizedSet(new LinkedHashSet<>());

	// Sweep state — only touched on the executor thread.
	private final List<Integer> sweepOrder = new ArrayList<>();
	private int batchIndex;
	private int roundIndex;
	private int posInBatch;
	private long lastPanelUpdateMs;

	@Override
	protected void startUp()
	{
		log.debug("Ping Worlds started");

		// Sidebar panel + nav button (works logged out, so you can pick a world before logging in).
		panel = new PingWorldsPanel(this::switchToWorld);
		navButton = NavigationButton.builder()
			.tooltip("Ping Worlds")
			.icon(createNavIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		// A single background thread. Pings are blocking network IO, which must NEVER run on the
		// game (client) thread — that would freeze RuneLite's UI.
		executor = Executors.newSingleThreadScheduledExecutor();
		pingTask = executor.schedule(this::tick, INITIAL_DELAY_SECONDS, TimeUnit.SECONDS);
	}

	@Override
	protected void shutDown()
	{
		// Cancel the scheduled task AND stop the executor. Per AGENTS.md: explicitly cancel the
		// future, use shutdownNow(), and never block shutDown() with awaitTermination().
		if (pingTask != null)
		{
			pingTask.cancel(true);
			pingTask = null;
		}
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
		statsByWorld.clear();
		pinned.clear();
		sweepOrder.clear();
		batchIndex = 0;
		roundIndex = 0;
		posInBatch = 0;

		log.debug("Ping Worlds stopped");
	}

	/** One scheduler tick: ping a single world, then schedule the next tick a steady spacing later. */
	private void tick()
	{
		try
		{
			sweepStep();
		}
		catch (Exception e)
		{
			// A thrown task would silently stop the scheduler, so swallow and log instead.
			log.debug("Sweep step failed", e);
		}
		finally
		{
			ScheduledExecutorService ex = executor;
			if (ex != null && !ex.isShutdown())
			{
				pingTask = ex.schedule(this::tick, PING_SPACING_MS, TimeUnit.MILLISECONDS);
			}
		}
	}

	/**
	 * Runs on the executor thread (never the client thread). Pings ONE world, advancing through the
	 * relevance-ordered sweep in batches: each world is pinged {@link #ROUNDS_PER_BATCH} times within
	 * its batch before we move on, and a batch is not revisited until the whole sweep completes.
	 */
	private void sweepStep()
	{
		WorldResult worldResult = worldService.getWorlds();
		if (worldResult == null)
		{
			return; // world list not loaded yet
		}

		if (sweepOrder.isEmpty())
		{
			rebuildSweep(worldResult);
		}
		if (sweepOrder.isEmpty())
		{
			maybeUpdatePanel(worldResult);
			return;
		}

		int total = sweepOrder.size();
		int batchCount = (total + BATCH_SIZE - 1) / BATCH_SIZE;
		if (batchIndex >= batchCount)
		{
			// Full sweep complete — rebuild (worlds / pins / populations may have changed) and restart.
			rebuildSweep(worldResult);
			if (sweepOrder.isEmpty())
			{
				maybeUpdatePanel(worldResult);
				return;
			}
			total = sweepOrder.size();
			batchCount = (total + BATCH_SIZE - 1) / BATCH_SIZE;
		}

		int batchStart = batchIndex * BATCH_SIZE;
		int batchSize = Math.min(BATCH_SIZE, total - batchStart);
		if (posInBatch >= batchSize)
		{
			posInBatch = 0;
		}

		int worldId = sweepOrder.get(batchStart + posInBatch);
		World world = worldResult.findWorld(worldId);
		if (world != null)
		{
			// Reuse RuneLite World Hopper's ping: native ICMP first, TCP-connect fallback if it fails
			// (the true flag). The native code lives in runelite-client, so our plugin uses no JNA.
			int ping = Ping.ping(world, true);
			statsByWorld.computeIfAbsent(worldId, id -> new WorldPingStats(config.sampleWindow()))
				.record(ping);
		}

		advanceSweep(batchSize);
		maybeUpdatePanel(worldResult);
	}

	private void advanceSweep(int batchSize)
	{
		posInBatch++;
		if (posInBatch >= batchSize)
		{
			posInBatch = 0;
			roundIndex++;
			if (roundIndex >= ROUNDS_PER_BATCH)
			{
				roundIndex = 0;
				batchIndex++; // next step rebuilds/restarts if this passes the last batch
			}
		}
	}

	/**
	 * Rebuilds the relevance-ordered sweep list: the current world and any pinned worlds first, then
	 * every eligible world (all regions, both member/f2p subgroups) ordered by your region, then your
	 * account subgroup, then emptiest. Resets the sweep position.
	 */
	private void rebuildSweep(WorldResult worldResult)
	{
		sweepOrder.clear();
		batchIndex = 0;
		roundIndex = 0;
		posInBatch = 0;

		int current = client.getWorld();
		LinkedHashSet<Integer> order = new LinkedHashSet<>();
		if (current > 0)
		{
			order.add(current);
		}
		synchronized (pinned)
		{
			order.addAll(pinned);
		}

		if (config.profile() == PingProfile.CUSTOM)
		{
			order.addAll(WorldListParser.parse(config.customWorlds()));
			sweepOrder.addAll(order);
			return;
		}

		WorldFilter filter = buildFilter(worldResult, current);
		WorldRegion myRegion = filter.getRegion();
		boolean membersPref = config.accountType() == AccountType.MEMBERS;

		List<World> eligible = new ArrayList<>();
		for (World w : worldResult.getWorlds())
		{
			WorldInfo info = new WorldInfo(w.getId(), w.getPlayers(), w.getRegion(), w.getActivity(), w.getTypes());
			if (WorldSelector.eligible(info, filter))
			{
				eligible.add(w);
			}
		}
		eligible.sort(Comparator
			.comparing((World w) -> !(myRegion != null && w.getRegion() == myRegion)) // your region first
			.thenComparing((World w) -> membersPref != w.getTypes().contains(WorldType.MEMBERS)) // your subgroup first
			.thenComparingInt(World::getPlayers)); // emptiest first within each group

		for (World w : eligible)
		{
			order.add(w.getId());
		}
		sweepOrder.addAll(order);
	}

	/**
	 * Builds the world filter from config: the selected play-style profile provides the rules, and
	 * region AUTO resolves to the region of the currently selected world.
	 */
	private WorldFilter buildFilter(WorldResult worldResult, int seedId)
	{
		WorldRegion region;
		if (config.region() == RegionOption.AUTO)
		{
			World seed = worldResult.findWorld(seedId);
			region = seed != null ? seed.getRegion() : null;
		}
		else
		{
			region = config.region().toWorldRegion();
		}

		return ProfileFilter.forProfile(config.profile(), region, config.accountType(), FULL_WORLD_PLAYERS);
	}

	private void maybeUpdatePanel(WorldResult worldResult)
	{
		long now = System.currentTimeMillis();
		if (now - lastPanelUpdateMs >= PANEL_REFRESH_MS)
		{
			lastPanelUpdateMs = now;
			updatePanel(worldResult);
		}
	}

	/**
	 * Builds the display model — the current world, pinned worlds, and the best profile-relevant
	 * worlds (up to the configured count) — and pushes it to the panel on the Swing thread, sorted
	 * best-first. Runs on the executor thread.
	 */
	private void updatePanel(WorldResult worldResult)
	{
		final PingWorldsPanel p = panel;
		if (p == null)
		{
			return;
		}

		final int avgT = config.avgThresholdMs();
		final int jitT = config.jitterThresholdMs();
		final int current = client.getWorld();
		final int limit = config.worldsToShow();

		LinkedHashSet<Integer> shown = new LinkedHashSet<>();
		if (current > 0)
		{
			shown.add(current);
		}
		synchronized (pinned)
		{
			shown.addAll(pinned);
		}

		List<World> relevant = new ArrayList<>();
		if (config.profile() == PingProfile.CUSTOM)
		{
			for (int id : WorldListParser.parse(config.customWorlds()))
			{
				World w = worldResult.findWorld(id);
				if (w != null)
				{
					relevant.add(w);
				}
			}
		}
		else
		{
			WorldFilter filter = buildFilter(worldResult, current);
			for (World w : worldResult.getWorlds())
			{
				WorldInfo info = new WorldInfo(w.getId(), w.getPlayers(), w.getRegion(), w.getActivity(), w.getTypes());
				if (WorldSelector.passes(info, filter))
				{
					relevant.add(w);
				}
			}
		}

		relevant.sort(Comparator.comparingDouble((World w) -> displayScore(w.getId(), avgT, jitT)));
		for (World w : relevant)
		{
			if (shown.size() >= limit)
			{
				break;
			}
			shown.add(w.getId());
		}

		final List<WorldStatus> rows = new ArrayList<>();
		for (int id : shown)
		{
			rows.add(buildStatus(id, worldResult, avgT, jitT));
		}
		rows.sort(Comparator
			.comparing(WorldStatus::hasData).reversed()
			.thenComparingInt(WorldStatus::getAverage)
			.thenComparingInt(WorldStatus::getWorldId));

		final String status = config.profile() + " · " + config.region();
		SwingUtilities.invokeLater(() -> p.display(rows, current, status));
	}

	/** Lower = better (shown first): consistent worlds by average, then unstable, then no-data last. */
	private double displayScore(int id, int avgT, int jitT)
	{
		WorldPingStats s = statsByWorld.get(id);
		if (s == null || !s.hasData())
		{
			return 100_000;
		}
		return s.isConsistent(avgT, jitT) ? s.average() : 10_000 + s.average();
	}

	private WorldStatus buildStatus(int id, WorldResult worldResult, int avgT, int jitT)
	{
		World w = worldResult.findWorld(id);
		String activity = w != null && w.getActivity() != null ? w.getActivity() : "";
		int players = w != null ? w.getPlayers() : -1;
		String region = w != null ? regionLabel(w.getRegion()) : "";

		WorldPingStats s = statsByWorld.get(id);
		if (s == null || !s.hasData())
		{
			return new WorldStatus(id, region, players, activity, false, 0, 0, 0, false);
		}
		return new WorldStatus(id, region, players, activity, true,
			s.average(), s.jitter(), s.sampleCount(), s.isConsistent(avgT, jitT));
	}

	/** Switches (hops) to the given world AND pins it so it keeps being scanned. Called from the EDT. */
	private void switchToWorld(int worldId)
	{
		WorldResult worldResult = worldService.getWorlds();
		if (worldResult == null)
		{
			return;
		}
		World world = worldResult.findWorld(worldId);
		if (world == null)
		{
			return;
		}

		pinned.add(worldId); // keep monitoring this world even after we move on

		// changeWorld must run on the client thread. Works at the login screen (sets the world you
		// will log into) and in-game (hops), mirroring RuneLite's own World Hopper.
		clientThread.invoke(() ->
		{
			net.runelite.api.World rsWorld = client.createWorld();
			rsWorld.setActivity(world.getActivity());
			rsWorld.setAddress(world.getAddress());
			rsWorld.setId(world.getId());
			rsWorld.setLocation(world.getLocation());
			rsWorld.setPlayerCount(world.getPlayers());
			rsWorld.setTypes(WorldUtil.toWorldTypes(world.getTypes()));
			client.changeWorld(rsWorld);
		});
	}

	/** Short region code for display, e.g. "US". Empty when unknown. */
	private static String regionLabel(WorldRegion region)
	{
		if (region == null)
		{
			return "";
		}
		switch (region)
		{
			case UNITED_STATES_OF_AMERICA:
				return "US";
			case UNITED_KINGDOM:
				return "UK";
			case GERMANY:
				return "DE";
			case AUSTRALIA:
				return "AU";
			default:
				return region.name().substring(0, Math.min(2, region.name().length()));
		}
	}

	/** A simple generated nav-button icon (a green "signal" dot). A polished icon.png comes in M7. */
	private static BufferedImage createNavIcon()
	{
		BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(76, 175, 80));
		g.fillOval(5, 5, 14, 14);
		g.dispose();
		return image;
	}

	@Provides
	PingWorldsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PingWorldsConfig.class);
	}
}

package com.pingworlds;

import net.runelite.http.api.worlds.WorldRegion;
import net.runelite.http.api.worlds.WorldType;

/**
 * Maps a play-style profile to a concrete {@link WorldFilter}. A profile is just a named preset of
 * filter rules for a goal, so this is the single place that decides what each profile means.
 * (The CUSTOM profile is handled separately by the plugin's hand-typed world list, not here.)
 */
public final class ProfileFilter
{
	private ProfileFilter()
	{
	}

	public static WorldFilter forProfile(PingProfile profile, WorldRegion region,
		AccountType accountType, int maxPlayers)
	{
		boolean members = accountType == AccountType.MEMBERS;

		switch (profile)
		{
			case FREE_TO_PLAY:
				// A free-to-play goal always means f2p worlds, regardless of the account-type setting.
				return new WorldFilter(region, false, false, false, maxPlayers);

			case PVP:
				// Show PvP / high-risk / deadman / LMS worlds too.
				return new WorldFilter(region, members, true, false, maxPlayers);

			case LEAGUES:
				// Leagues run on SEASONAL worlds; require that type and allow seasonal through.
				return new WorldFilter(region, members, false, true, maxPlayers, WorldType.SEASONAL);

			case STABLE_BOSSING:
			case CUSTOM:
			default:
				// Standard, stable worlds: no PvP, no Leagues, no special worlds.
				return new WorldFilter(region, members, false, false, maxPlayers);
		}
	}
}

