package com.pingworlds;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Turns the user's free-text "custom worlds" field (e.g. "301, 302, 302, abc, 330") into a clean,
 * de-duplicated list of world numbers. Free text is where bad input sneaks in, so this is a pure,
 * unit-tested function — the "hard 20%" we don't want to hand-wave.
 */
public final class WorldListParser
{
	// OSRS world numbers sit in a modest band; reject clearly-bogus values (0, negatives, huge ints).
	// Kept generous on purpose so a new world block never gets silently dropped.
	private static final int MIN_WORLD = 300;
	private static final int MAX_WORLD = 1000;

	private WorldListParser()
	{
	}

	public static List<Integer> parse(String raw)
	{
		// LinkedHashSet de-dupes while preserving the order the user typed.
		Set<Integer> worlds = new LinkedHashSet<>();
		if (raw == null)
		{
			return new ArrayList<>();
		}

		for (String token : raw.split("[,\\s]+")) // split on any mix of commas and whitespace
		{
			if (token.isEmpty())
			{
				continue;
			}
			try
			{
				int world = Integer.parseInt(token);
				if (world >= MIN_WORLD && world <= MAX_WORLD)
				{
					worlds.add(world);
				}
				// out-of-range numbers are dropped rather than trusted
			}
			catch (NumberFormatException ignored)
			{
				// junk like "abc" — skip it instead of blowing up
			}
		}

		return new ArrayList<>(worlds);
	}
}

package com.pingworlds;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Rolling ping statistics for a single world. Keeps the most recent N successful pings and computes
 * average latency and jitter (population standard deviation = how much the pings bounce around).
 * Timeouts (Ping.ping returns -1) are counted separately, never mixed into the latency math.
 *
 * Thread-safety: pings are recorded on the background executor thread and read later from the Swing
 * UI thread (M6), so every method is synchronized.
 */
public class WorldPingStats
{
	private final int windowSize;
	private final Deque<Integer> samples = new ArrayDeque<>(); // successful pings only, oldest first
	private int timeouts;

	public WorldPingStats(int windowSize)
	{
		this.windowSize = Math.max(1, windowSize);
	}

	/** Record one ping result. A negative value means the ping timed out / failed. */
	public synchronized void record(int pingMs)
	{
		if (pingMs < 0)
		{
			timeouts++;
			return; // don't pollute latency stats with a failed ping
		}
		samples.addLast(pingMs);
		while (samples.size() > windowSize)
		{
			samples.removeFirst(); // keep only the most recent windowSize successes
		}
	}

	public synchronized int sampleCount()
	{
		return samples.size();
	}

	public synchronized boolean hasData()
	{
		return !samples.isEmpty();
	}

	public synchronized int timeouts()
	{
		return timeouts;
	}

	/** Mean of the recent successful pings, rounded to the nearest ms. 0 if there is no data. */
	public synchronized int average()
	{
		if (samples.isEmpty())
		{
			return 0;
		}
		long sum = 0;
		for (int s : samples)
		{
			sum += s;
		}
		return Math.round((float) sum / samples.size());
	}

	/**
	 * Jitter = population standard deviation of the recent pings, rounded to ms. Needs at least two
	 * samples to mean anything, so returns 0 below that.
	 */
	public synchronized int jitter()
	{
		int n = samples.size();
		if (n < 2)
		{
			return 0;
		}
		double mean = 0;
		for (int s : samples)
		{
			mean += s;
		}
		mean /= n;

		double sumSquares = 0;
		for (int s : samples)
		{
			double diff = s - mean;
			sumSquares += diff * diff;
		}
		return (int) Math.round(Math.sqrt(sumSquares / n));
	}

	/**
	 * The green-check rule: a world is "consistent" (good to log into) when it has data and both its
	 * average latency and its jitter are at or under the user's thresholds. This is the single source
	 * of truth for green vs red — the panel (M6) will call exactly this.
	 */
	public synchronized boolean isConsistent(int avgThresholdMs, int jitterThresholdMs)
	{
		return hasData()
			&& average() <= avgThresholdMs
			&& jitter() <= jitterThresholdMs;
	}
}

package com.pingworlds;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.EnumSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.http.api.worlds.WorldType;

/**
 * Pure world-selection logic: take the full world list, keep the ones matching a filter, and pick
 * the emptiest N — always evaluating the currently-selected world too. No RuneLite client needed,
 * so every rule here is unit-tested.
 */
public final class WorldSelector
{
	// Hard cap regardless of requested count (the DDoS guardrail is also enforced in the plugin).
	static final int MAX_ACTIVE_WORLDS = 8;

	// PvP-style worlds: risky to log into by accident, excluded unless a profile opts in.
	private static final Set<WorldType> PVP_TYPES = EnumSet.of(
		WorldType.PVP, WorldType.PVP_ARENA, WorldType.HIGH_RISK, WorldType.BOUNTY,
		WorldType.LAST_MAN_STANDING, WorldType.DEADMAN);

	// Leagues run on SEASONAL worlds (there is no WorldType.LEAGUE).
	private static final Set<WorldType> SEASONAL_TYPES = EnumSet.of(WorldType.SEASONAL);

	// Non-standard worlds we never treat as a normal login target.
	private static final Set<WorldType> ALWAYS_EXCLUDED = EnumSet.of(
		WorldType.SKILL_TOTAL, WorldType.TOURNAMENT, WorldType.BETA_WORLD,
		WorldType.FRESH_START_WORLD, WorldType.NOSAVE_MODE, WorldType.QUEST_SPEEDRUNNING);

	private WorldSelector()
	{
	}

	/**
	 * @param all         every known world (as pure snapshots)
	 * @param filter      the rules for which worlds are candidates
	 * @param seedWorldId the currently-selected world; always included first if online (even if it
	 *                    fails the filter), so you can always compare your current world
	 * @param count       how many worlds to return (clamped to [0, MAX_ACTIVE_WORLDS])
	 * @return world ids, seed first, then the emptiest matching worlds
	 */
	public static List<Integer> select(List<WorldInfo> all, WorldFilter filter, int seedWorldId, int count)
	{
		int limit = Math.min(Math.max(count, 0), MAX_ACTIVE_WORLDS);
		LinkedHashSet<Integer> result = new LinkedHashSet<>();
		if (all == null || all.isEmpty() || limit == 0)
		{
			return new ArrayList<>(result);
		}

		// 1) Always evaluate the currently-selected world (if online), even if it fails the filter.
		WorldInfo seed = findById(all, seedWorldId);
		if (seed != null && seed.getPlayers() >= 0)
		{
			result.add(seed.getId());
		}

		// 2) Fill the rest with the emptiest matching worlds (ties broken by id for determinism).
		all.stream()
			.filter(w -> passes(w, filter))
			.sorted(Comparator.comparingInt(WorldInfo::getPlayers).thenComparingInt(WorldInfo::getId))
			.forEach(w ->
			{
				if (result.size() < limit)
				{
					result.add(w.getId());
				}
			});

		return new ArrayList<>(result);
	}

	/** True if a world passes the full filter (region + members + type rules). */
	static boolean passes(WorldInfo w, WorldFilter f)
	{
		if (!eligible(w, f))
		{
			return false;
		}

		boolean isMembers = w.hasType(WorldType.MEMBERS);
		if (f.isRequireMembers() != isMembers)
		{
			return false; // members account wants members worlds; f2p wants free worlds
		}

		if (f.getRegion() != null && w.getRegion() != f.getRegion())
		{
			return false; // wrong region (a null world region never matches a specific target)
		}

		return true;
	}

	/**
	 * True if a world is online and passes only the TYPE rules (full/offline, required type, PvP,
	 * Leagues, special) — ignoring region and members. Used by the full sweep, which scans every
	 * region and both member/f2p subgroups (ordering handles relevance, not filtering).
	 */
	static boolean eligible(WorldInfo w, WorldFilter f)
	{
		if (w.getPlayers() < 0)
		{
			return false; // offline
		}
		if (w.isGeneric() && w.getPlayers() >= f.getMaxPlayers())
		{
			return false; // full — but only for generic worlds; keep busy activity worlds (e.g. Trade)
		}
		if (f.getRequiredType() != null && !w.hasType(f.getRequiredType()))
		{
			return false; // profile requires a specific world type (e.g. Leagues = SEASONAL)
		}
		if (!f.isIncludePvp() && intersects(w, PVP_TYPES))
		{
			return false;
		}
		if (!f.isIncludeLeagues() && intersects(w, SEASONAL_TYPES))
		{
			return false;
		}
		if (intersects(w, ALWAYS_EXCLUDED))
		{
			return false;
		}
		return true;
	}

	private static boolean intersects(WorldInfo w, Set<WorldType> types)
	{
		for (WorldType t : types)
		{
			if (w.hasType(t))
			{
				return true;
			}
		}
		return false;
	}

	private static WorldInfo findById(List<WorldInfo> all, int id)
	{
		if (id <= 0)
		{
			return null;
		}
		for (WorldInfo w : all)
		{
			if (w.getId() == id)
			{
				return w;
			}
		}
		return null;
	}
}

